from audit_experiments import make_fixture  # noqa: E402


def show_state(f, label):
    with SqliteSaver.from_conn_string(str(f.directory / "pipeline.sqlite")) as saver:
        state = build_pipeline(saver, f.runtime).get_state(f.config)
    print(f"{label}: next={state.next} tasks={[(t.name, repr(t.error)[:80]) for t in state.tasks]}")


def run(kind):
    f = make_fixture()
    try:
        if kind == "launch":
            real = f.sessions.run_reviewer
            def launched_then_interrupted(prompt, token, candidate):
                real(prompt, token, candidate)
                raise KeyboardInterrupt
            context = patch.object(f.sessions, "run_reviewer", side_effect=launched_then_interrupted)
        else:
            real_wait = automatic.wait_review
            marker = {"armed": True}
            def interrupted_once(runtime, **kwargs):
                if marker["armed"]:
                    marker["armed"] = False
                    raise KeyboardInterrupt
                return real_wait(runtime, **kwargs)
            context = patch("workflow.automatic.wait_review", side_effect=interrupted_once)
        with patch("workflow.automatic.wait_handoffs"), context:
            try:
                drive(f.runtime)
            except KeyboardInterrupt:
                print(kind, ": KeyboardInterrupt propagated out of drive")
        show_state(f, kind + " after interrupt")
        print(kind, "automatic-review.json:", {k: read_json(f.directory / "automatic-review.json").get(k) for k in ("status", "error")})
        with patch("workflow.automatic.wait_handoffs"):
            try:
                commit = drive(f.runtime)
                print(kind, ": resume completed, commit", commit[:8])
            except Exception as error:
                print(kind, ": resume raised", type(error).__name__, error)
        show_state(f, kind + " after resume")
    finally:
        f.doCleanups()


if __name__ == "__main__":
    for kind in sys.argv[1:] or ("wait", "launch"):
        run(kind)

